/**
 * Third-party notices for the in-app "Open-source licenses" screen.
 *
 * `notices.json` is generated by `tools/licenses/generate.py` (do not edit it
 * by hand). It is imported as a raw string in its own chunk, so it is only
 * loaded when the screen opens and works offline.
 */

export const NOTICE_GROUPS = [
  'rust-server',
  'rust-app',
  'npm',
  'fonts',
  'android',
  'native',
  'other',
] as const;
export type NoticeGroup = (typeof NOTICE_GROUPS)[number];

export interface NoticePackage {
  /** Name (crate, npm package, Maven group:artifact). */
  n: string;
  /** Version. */
  v: string;
  /** License used (elected from the declared expression). */
  l: string;
  /** Declared license expression. */
  d: string;
  /** Repository or project URL. */
  r: string;
  /** Component groups. */
  g: NoticeGroup[];
  /** Copyright lines. */
  c: string[];
  /** MPL-2.0: source code URL. */
  s?: string;
  /** Extra note. */
  x?: string;
}

export interface Notices {
  notices: string;
  groups: NoticeGroup[];
  /** `[license, count]`, most common first. */
  counts: [string, number][];
  packages: NoticePackage[];
  /** License texts by SPDX id. */
  texts: Record<string, string>;
  /** Non-open-source terms by id. */
  proprietary: Record<string, { label: string; url: string }>;
}

let cache: Promise<Notices> | null = null;

export function loadNotices(): Promise<Notices> {
  cache ??= import('./notices.json?raw').then((m) => JSON.parse(m.default) as Notices);
  return cache;
}

/** SPDX ids whose texts apply to a license such as `MIT AND Unicode-3.0`. */
export function licenseIds(license: string): string[] {
  return license.split(' AND ').flatMap((part) => part.split(' WITH '));
}

/** Case-insensitive match on name, license or declared expression. */
export function matchesQuery(pkg: NoticePackage, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return (
    pkg.n.toLowerCase().includes(q) ||
    pkg.l.toLowerCase().includes(q) ||
    pkg.d.toLowerCase().includes(q)
  );
}
